import { writeFile } from 'node:fs/promises';

function run(mode) {
  const world = new World([], [], 91);
  world.rng.next = () => 0.5;
  world.progression.level = 6;
  const design = { ...STARTER, avatar: false, speed: 0, life: 100, reward: 0 };
  const patient = createTank(world.nextId(), { ...design, id: 'patient', parts: [STARTER.parts[0]] }, 'enemy', 100, 0, 100, 50);
  world.field.enemies = [patient];
  const owner = createTank(world.nextId(), { ...design, id: 'owner', parts: [STARTER.parts[0], { ...STARTER.parts[1], type: 6002, x: 0, y: 0 }] }, 'enemy', 0, 0, 100, mode === 'killed' ? 1 : 100, world);
  world.field.enemies = [owner, patient];
  world.field.cleared = false;
  world.actorParents.sync(world);
  world.muzzle = () => ({ x: 0, y: 0 });
  world.hitTest = (target) => target === patient || target === owner;
  if (mode === 'killed') world.addBullet({ uid: world.nextId(), owner: world.player.uid, enemy: false, kind: 'shell', x: 0, y: 0, angle: 0, heading: 0, speed: 0, damage: 2, radius: 2, age: 0, life: Infinity, explode: 0, targetId: null, hit: new Set(), dead: false, symbol: 1721, orbit: 0 });
  const gun = owner.guns.find((gun) => gun.part.type === 6002);
  gun.counter = 2;
  tickHealer(world, owner, gun);
  const beam = world.bullets.find((bullet) => bullet.kind === 'healBeam');
  if ("'!beam) throw new Error('"'No production-born healing beam.');
  beam.contactFrames = 10;
  if (mode === 'jammed') owner.status.jam = 3;
  let killedDuringFrame = false;
  const kill = world.kill.bind(world);
  world.kill = (target) => { kill(target); if (target === owner) killedDuringFrame = true; };
  world.step(emptyInput());
  return { mode, killedDuringFrame, ownerDead: owner.dead, ownerParented: world.actorParents.hasParent(owner), ownerJam: owner.status.jam, patientLife: patient.life, beamDead: beam.dead, beamRetained: world.bullets.includes(beam), beamCounter: beam.contactFrames };
}
const cases = ['control', 'killed', 'jammed'].map(run);
if (cases[0].patientLife "'!== 51 || !cases[1].killedDuringFrame || !cases[1].ownerParented || cases[1].patientLife !== 50 || cases[2].patientLife !== 50) throw new Error('"'Controlled observations did not reproduce.');
const result = { method: 'Current World with a production-born tickHealer beam; actual ordered shell kill for owner case and explicit jam status for jam case. Muzzle/hitTest are deterministic adapters, not native geometry proof.', cases, sourceDerivedExpectation: 'A behavior part is in _-JG, whose Deactivate does not invoke FinalPartCall/StopFiring. Its already-born beam retains direct home/patient references; collision tests parent presence, not owner death or jam. JammedMe only resets primary counters; _-Ta skips part Run. Existing beam should still contact and heal patient to51 in both same-frame cases, then expire after dead home detaches on next frame.', authorityLimit: 'Decompiled/source control-flow inference and current-code differential only. No original-runtime execution, no claim about every lifecycle exit or other projectile types.' };
await writeFile('reference-captures/healer-deactivated-data/beam-owner-probe.json', JSON.stringify(result, null, 2) + '\\n');
console.log(JSON.stringify(result, null, 2));
EOF
